const $=s=>document.querySelector(s), stage=$('#stage'),center=$('#center'),canvas=$('#game'),ctx=canvas.getContext('2d');
let mode='classic',count=5,state='idle',scores=[],timer=0,started=0,history=[];
try{history=JSON.parse(localStorage.getItem('reflex-history')||'[]')}catch{}
let side=1,enemyX=0,player=400,enemyStart=0,keys={},anim=0,shots=0,hits=0,aim={x:400,y:180},lastFrame=0,lockedX=null,flashUntil=0;
const palettes={desert:{sky:'#cdb996',floor:'#a98e65',wall:'#816d52',edge:'#e6d1a7',line:'#d9c39a',uniform:'#8c7855',dark:'#4f473c'},mountain:{sky:'#667f71',floor:'#455d4b',wall:'#304638',edge:'#8ba08a',line:'#718773',uniform:'#5d6d47',dark:'#26382f'},snow:{sky:'#bacbd0',floor:'#e1e9e7',wall:'#8b9da1',edge:'#f5faf8',line:'#adbdc0',uniform:'#d3ddda',dark:'#52666a'}};
let scene='desert';const counts=[3,5,10,15,20,30,100];
function settings(){ $('#counts').innerHTML=counts.map(n=>`<button class="${n===count?'active':''}" data-n="${n}">${n}</button>`).join('');document.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>{count=+b.dataset.n;settings();reset()}) }
function records(){ $('#records').innerHTML=history.length?history.slice(0,10).map(h=>`<div class="record"><b>${h.value}</b><span>${h.mode} · ${h.count} 次<br>${h.date}</span></div>`).join(''):'<div class="empty">还没有记录，开始你的第一次测试吧。</div>';let relevant=history.filter(h=>h.mode===(mode==='classic'?'经典反应':'拐角遭遇'));$('#stat').innerHTML='最佳成绩 <b>'+(relevant.length?relevant.map(x=>x.value).sort((a,b)=>parseInt(a)-parseInt(b))[0]:'—')+'</b>' }
function save(value){history.unshift({mode:mode==='classic'?'经典反应':'拐角遭遇',value,count,date:new Date().toLocaleDateString('zh-CN')});history=history.slice(0,30);try{localStorage.setItem('reflex-history',JSON.stringify(history))}catch{}records()}
function reset(){clearTimeout(timer);cancelAnimationFrame(anim);state='idle';stage.style.background='';scores=[];shots=hits=0;player=400;keys={};stage.className='stage';canvas.hidden=true;$('#mobile-controls').hidden=true;$('#scene-settings').hidden=mode!=='corner';$('#progress').textContent='READY / 准备就绪';$('#title').textContent=mode==='classic'?'经典反应测试':'拐角遭遇测试';$('#instruction').textContent=mode==='classic'?'观察圆点变化，变绿时立即点击':'A / D 移动人物 · 鼠标移动瞄准，点击射击 · 对手锁定后移动可躲避';center.innerHTML=mode==='classic'?'<div class="orb"></div><h3>准备好了吗？</h3><p>等待红色变绿，然后尽快点击</p><button class="start" id="start">开始测试　↗</button>':'<div style="font-size:58px;color:#c6f36b;margin-bottom:20px">⌖</div><h3>拐角遭遇</h3><p>目标会从掩体后出现、移动并开火。<br>移动人物，瞄准并抢先命中。</p><button class="start" id="start">进入训练　↗</button>';$('#start').onclick=e=>{e.stopPropagation();mode==='classic'?round():cornerRound()};records()}
function round(){state='waiting';stage.className='stage wait';stage.style.background=$('#assist').checked?'#634e83':'';center.innerHTML='<div class="orb"></div><h3>等待信号…</h3><p>保持专注，先不要点击</p>';$('#progress').textContent=`ROUND ${scores.length+1} / ${count}`;timer=setTimeout(()=>{state='go';stage.className='stage go';stage.style.background=$('#assist').checked?'#2f7085':'';center.innerHTML='<div class="orb"></div><h3>现在点击！</h3><p>点击屏幕任意位置</p>';started=performance.now()},1200+Math.random()*3000)}
function finish(){state='done';stage.className='stage';canvas.hidden=true;$('#mobile-controls').hidden=true;cancelAnimationFrame(anim);let valid=scores.filter(x=>x!=null),avg=valid.length?Math.round(valid.reduce((a,b)=>a+b,0)/valid.length):0;let value=valid.length?avg+' ms':'未命中';if(valid.length)save(value);center.innerHTML=`<div style="font-size:12px;letter-spacing:.15em;color:#c6f36b">TEST COMPLETE</div><h3 style="font-size:52px;margin:15px 0">${value}</h3><p>${mode==='classic'?'平均反应时间':'平均命中时间 · 命中 '+hits+' / '+count+' · 射击 '+shots+' 次'}</p><p class="round-results">${valid.length?'每轮：'+scores.map(x=>x==null?'未命中':Math.round(x)+'ms').join(' / '):'再试一次，等待目标出现。'}</p><button class="start" id="again">再测一次　↗</button>`;$('#progress').textContent='COMPLETE / 测试完成';$('#again').onclick=e=>{e.stopPropagation();reset()}}
function pointerPosition(e){const r=canvas.getBoundingClientRect();aim.x=Math.max(0,Math.min(800,(e.clientX-r.left)/r.width*800));aim.y=Math.max(0,Math.min(440,(e.clientY-r.top)/r.height*440))}
stage.addEventListener('pointermove',e=>{if(mode==='corner'&&!canvas.hidden)pointerPosition(e)});
stage.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;if(mode==='classic'){if(state==='waiting'){clearTimeout(timer);state='early';stage.style.background='';stage.className='stage early';center.innerHTML='<div class="orb"></div><h3>太早了！</h3><p>等到信号出现再点击</p><button class="start" id="retry">重试本轮　↗</button>';$('#retry').onclick=ev=>{ev.stopPropagation();round()}}else if(state==='go'){scores.push(performance.now()-started);state='between';stage.style.background='';stage.className='stage';center.innerHTML=`<div class="orb" style="background:#c6f36b"></div><h3>${Math.round(scores.at(-1))} ms</h3><p>${scores.length===count?'测试完成':'点击继续下一轮'}</p>`;if(scores.length===count)timer=setTimeout(finish,650)}else if(state==='between'&&scores.length<count)round()}else if(state==='enemy'||state==='cornerwait'){pointerPosition(e);shots++;flashUntil=performance.now()+100;if(state==='enemy'&&Math.abs(aim.x-enemyX)<33&&aim.y>132&&aim.y<300){hits++;scores.push(performance.now()-enemyStart);nextCorner('命中！')}}});
function cornerRound(){state='cornerwait';stage.className='stage shooting';canvas.hidden=false;$('#mobile-controls').hidden=false;center.innerHTML='';side=Math.random()<.5?-1:1;lockedX=null;$('#progress').textContent=`ROUND ${scores.length+1} / ${count}`;lastFrame=performance.now();cancelAnimationFrame(anim);anim=requestAnimationFrame(draw);timer=setTimeout(()=>{state='enemy';enemyStart=performance.now()},1000+Math.random()*2500)}
function nextCorner(message){state='cornerbetween';clearTimeout(timer);cancelAnimationFrame(anim);center.innerHTML=`<div class="result-badge"><h3>${message}</h3><p>${scores.length} / ${count}</p></div>`;timer=setTimeout(()=>{center.innerHTML='';scores.length>=count?finish():cornerRound()},850)}
function draw(now){if(!['cornerwait','enemy'].includes(state))return;const dt=Math.min(40,now-lastFrame);lastFrame=now;let dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);player=Math.max(90,Math.min(710,player+dir*dt*.26));const p=palettes[scene];canvas.width=800;canvas.height=440;ctx.fillStyle=p.sky;ctx.fillRect(0,0,800,440);ctx.fillStyle=p.floor;ctx.fillRect(0,300,800,140);ctx.strokeStyle=p.line;ctx.globalAlpha=.35;for(let i=0;i<9;i++){ctx.beginPath();ctx.moveTo(i*110,300);ctx.lineTo(i*160-200,440);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle=p.wall;ctx.fillRect(0,0,165,320);ctx.fillRect(635,0,165,320);ctx.fillStyle=p.edge;ctx.fillRect(155,0,10,320);ctx.fillRect(635,0,10,320);for(let i=0;i<5;i++){ctx.fillStyle=i%2?p.floor:p.dark;ctx.globalAlpha=.18;ctx.fillRect(i%2?24:75,40+i*53,70,19);ctx.fillRect(i%2?670:725,30+i*56,60,20)}ctx.globalAlpha=1;
if(state==='enemy'){let elapsed=now-enemyStart;enemyX=(side<0?170:630)+(-side)*Math.min(105,elapsed*.11)+Math.sin(elapsed/240)*18;ctx.fillStyle='#d7a486';ctx.beginPath();ctx.arc(enemyX,158,20,0,7);ctx.fill();ctx.fillStyle=p.uniform;ctx.fillRect(enemyX-28,180,56,75);ctx.fillStyle=p.dark;ctx.fillRect(enemyX-25,252,19,48);ctx.fillRect(enemyX+6,252,19,48);ctx.save();ctx.translate(enemyX,200);ctx.rotate(Math.atan2(390-200,player-enemyX));ctx.fillStyle=p.dark;ctx.fillRect(0,-4,44,8);ctx.restore();if(elapsed>1000&&lockedX===null)lockedX=player;if(lockedX!==null){ctx.strokeStyle='#eab671';ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(enemyX,200);ctx.lineTo(lockedX,400);ctx.stroke();ctx.setLineDash([])}if(elapsed>2300){if(Math.abs(player-lockedX)<45){scores.push(null);nextCorner('被击中！');return}else{scores.push(null);nextCorner('躲开了！');return}}}
// Player avatar and independently aimed weapon.
ctx.fillStyle=p.dark;ctx.beginPath();ctx.arc(player,355,16,0,7);ctx.fill();ctx.fillStyle=p.uniform;ctx.fillRect(player-22,370,44,52);ctx.fillStyle=p.dark;ctx.fillRect(player-20,418,16,22);ctx.fillRect(player+4,418,16,22);ctx.save();ctx.translate(player,382);ctx.rotate(Math.atan2(aim.y-382,aim.x-player));ctx.fillStyle='#303831';ctx.fillRect(0,-5,52,10);ctx.fillRect(25,4,10,9);if(now<flashUntil){ctx.fillStyle='#ffd46c';ctx.beginPath();ctx.arc(56,0,8,0,7);ctx.fill()}ctx.restore();ctx.strokeStyle='#f4f3db';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(aim.x-10,aim.y);ctx.lineTo(aim.x+10,aim.y);ctx.moveTo(aim.x,aim.y-10);ctx.lineTo(aim.x,aim.y+10);ctx.stroke();ctx.fillStyle=p.dark;ctx.font='bold 14px sans-serif';ctx.fillText(state==='enemy'?(lockedX===null?'目标出现！':'对手已锁定，快移动！'):'保持警惕，目标即将出现…',20,28);anim=requestAnimationFrame(draw)}
window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['ArrowLeft','ArrowRight'].includes(e.key)&&mode==='corner'&&state!=='idle')e.preventDefault()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>keys={});document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));reset()});document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{scene=b.dataset.scene;document.querySelectorAll('[data-scene]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelectorAll('[data-move]').forEach(b=>{let key=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[key]=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys[key]=false)});$('#clear').onclick=()=>{history=[];try{localStorage.removeItem('reflex-history')}catch{}records()};settings();reset();
